  "headline": "Gabapentin is not on FDA's shortage list as of 2026-10-21; Corvale East has 7.1 days on hand and Corvale Lakeside has 18 days on hand",
  "headline_cites": ["D4", "D1", "D3"],
  "sentences": [
    {
      "text": "FDA's records show gabapentin is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 115 capsules of gabapentin 100 mg at 16.1 per day, giving 7.1 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale Lakeside holds 82 capsules of gabapentin 100 mg at 4.6 per day, giving 18 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "Both sites' supply is labeled by STALLION LABORATORIES PRIVATE LIMITED (NDC 72737000503).",
      "cites": ["E1", "E3"]
    },
    {
      "text": "The plant for this label is STALLION LABORATORIES PRIVATE LIMITED (FEI 3013353854) in India, last inspected 2024-07-12 with a VAI classification.",
      "cites": ["E5", "E4"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 18 capsules of 100 mg from Corvale Lakeside to Corvale East, which would raise Corvale East to about 8 days on hand while Corvale Lakeside retains two weeks of supply.",
      "cites": ["D5"]
    }
  ]
}
